using System.Security.Cryptography;
using System.Text;
using RnRomManager.Core.Storage;

namespace RnRomManager.Core.Tests.Storage;

public class RomFileHasherTests
{
    /// <summary>Serves <paramref name="length"/> generated bytes in reads of at most <paramref name="chunk"/>, never holding them all.</summary>
    private sealed class GeneratedStream(long length, int chunk) : Stream
    {
        public long BytesServed { get; private set; }

        public static byte At(long position) => (byte)((position * 31) + (position >> 8));

        public override int Read(byte[] buffer, int offset, int count)
        {
            var n = (int)Math.Min(Math.Min(count, chunk), length - BytesServed);
            for (var i = 0; i < n; i++)
                buffer[offset + i] = At(BytesServed + i);
            BytesServed += n;
            return n;
        }

        public override bool CanRead => true;
        public override bool CanSeek => false;
        public override bool CanWrite => false;
        public override long Length => throw new NotSupportedException();
        public override long Position { get => throw new NotSupportedException(); set => throw new NotSupportedException(); }
        public override void Flush() { }
        public override long Seek(long offset, SeekOrigin origin) => throw new NotSupportedException();
        public override void SetLength(long value) => throw new NotSupportedException();
        public override void Write(byte[] buffer, int offset, int count) => throw new NotSupportedException();
    }

    private static byte[] Bytes(int length) => [.. Enumerable.Range(0, length).Select(i => GeneratedStream.At(i))];

    [Test]
    public async Task KnownVector_123456789()
    {
        var bytes = Encoding.ASCII.GetBytes("123456789");

        var hashes = await RomFileHasher.HashAsync(new MemoryStream(bytes), long.MaxValue, default);

        Assert.That(hashes, Is.Not.Null);
        Assert.That((hashes!.SizeBytes, hashes.Crc32, hashes.Sha1), Is.EqualTo((9L, "cbf43926", "f7c3bc1d808e04732adf679965ccc34ca7ae3441")));
        Assert.That(hashes.Header, Is.EqualTo(bytes));
        Assert.That(Crc32.ToHex(bytes), Is.EqualTo("cbf43926"), "Compute still agrees after the incremental split");
    }

    // 4099 never divides the 1 MiB buffer or header, so reads straddle every boundary.
    [TestCase(0, 4099)]
    [TestCase(1, 1)]
    [TestCase(RomFileHasher.HeaderBytes - 1, 4099)]
    [TestCase(RomFileHasher.HeaderBytes, 4099)]
    [TestCase(RomFileHasher.HeaderBytes + 1, 4099)]
    [TestCase((3 * RomFileHasher.HeaderBytes) + 17, int.MaxValue)]
    public async Task MatchesWholeBufferHashes_AndKeepsAtMostOneMiBOfHeader(int length, int chunk)
    {
        var bytes = Bytes(length);

        var hashes = await RomFileHasher.HashAsync(new GeneratedStream(length, chunk), length, default);

        Assert.That(hashes, Is.Not.Null);
        Assert.That((hashes!.SizeBytes, hashes.Crc32, hashes.Md5, hashes.Sha1), Is.EqualTo(((long)length, Crc32.ToHex(bytes),
            Convert.ToHexStringLower(MD5.HashData(bytes)), Convert.ToHexStringLower(SHA1.HashData(bytes)))));
        Assert.That(hashes.Header.Length, Is.EqualTo(Math.Min(length, RomFileHasher.HeaderBytes)));
        Assert.That(hashes.Header.AsSpan().SequenceEqual(bytes.AsSpan(0, hashes.Header.Length)), Is.True);
    }

    [Test]
    public async Task OverTheCap_IsNull_AndStopsReading()
    {
        const long cap = 2L * 1024 * 1024;
        var stream = new GeneratedStream(64L * 1024 * 1024 * 1024, int.MaxValue); // 64 GiB: too big to buffer

        var hashes = await RomFileHasher.HashAsync(stream, cap, default);

        Assert.That(hashes, Is.Null);
        Assert.That(stream.BytesServed, Is.LessThanOrEqualTo(cap + (1024 * 1024)), "it stops at the first read past the cap");
    }

    [Test]
    public void Cancelled_Throws()
    {
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        Assert.That(async () => await RomFileHasher.HashAsync(new MemoryStream(new byte[10]), 10, cts.Token),
            Throws.InstanceOf<OperationCanceledException>());
    }
}
